#include <cstddef>
#include <optional>
#include <vector>

std::optional<std::size_t> findIndex(const std::vector<int>& values, int target)
{
    for (std::size_t i{ 0 }; i < values.size(); ++i)
    {
        if (values[i] == target)
        {
            return i;
        }
    }
    return std::nullopt;
}

unitTests:
TEST("found") { const auto i{ findIndex({ 5, 8, 13 }, 8) }; CHECK(i.has_value()); CHECK_EQ(i.value_or(99), 1u); CHECK_EQ(findIndex({ 5, 8, 13 }, 5).value_or(99), 0u); }
TEST("index zero is a real answer, not a missing one") { CHECK(findIndex({ 7 }, 7).has_value()); }
TEST("not found") { CHECK(!findIndex({ 5, 8, 13 }, 9)); CHECK(!findIndex({}, 1)); }

